import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const f=JSON.parse('{"title":"金刚经11分-随喜即众善","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经11分-随喜即众善.md","filePath":"60-原文段落/金刚经11分-随喜即众善.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经11分-随喜即众善.md"};function s(n,t,p,c,d,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经11分-随喜即众善" tabindex="-1">金刚经11分-随喜即众善 <a class="header-anchor" href="#金刚经11分-随喜即众善" aria-label="Permalink to &quot;金刚经11分-随喜即众善&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/11了空居士讲《金刚经》-第十一分无为福胜分20161111">11了空居士讲《金刚经》-第十一分无为福胜分20161111</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>了空居士</strong>：其实随喜功德是见贤思齐的第一步，一个人看到好人好事，你没有心生欢喜，那么可能就是很麻木啦，要不就反过来，就嫉妒啦。麻木呢，你就没有思齐，见贤你没有感触，就不可能思齐了。见贤你嫉妒就更加糟糕啦。所以说随喜是见贤思齐的第一步，你看他高兴认同，其实你为什么会喜呢？是你认同，觉得人家这么做很好。那么第二步要问，你愿不愿意跟他那么做啊？有没有迈开第二步啊？如果有，那你就不断地成就啦。</p><p>**主持：**看来随喜功德是我们修行很重要的部分。</p><p><strong>了空居士</strong>：哎呀，可以说非常重要！非常重要！从七佛通偈来说，诸恶莫作这个叫做本分，众善奉行这个才是真正的进入修行的状态啊，随喜就是众善奉行的第一步！</p>',6)])])}const m=e(_,[["render",s]]);export{f as __pageData,m as default};
